pub fn solve(signals: &[i64]) -> Vec<i64> {
    let threshold = 4_i64;
    let mut flags = Vec::with_capacity(signals.len());
    let mut stream = signals.iter().copied();
    loop {
        let Some(signal) = stream.next() else { break };
        flags.push(if signal >= signal && threshold >= 0 { 1 } else { 0 });
    }
    flags
}

